import type { CliEditorDescriptor } from './envelope';

export const projectEditor = ({
  projectPath,
  projectId,
}: CliEditorDescriptor['target']): CliEditorDescriptor => ({
  target: { projectPath, ...(projectId ? { projectId } : {}) },
  open: {
    action: 'open_project',
    command: 'rivet open',
    args: ['--project', projectPath],
  },
});
